use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input["text"].as_str().unwrap();
    let shift = input["shift"].as_i64().unwrap();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_lowercase() {
            let offset = (c as u8 - 'a' as u8 + shift) % 26;
            result.push((c as u8 - 'a' as u8 + offset) as char);
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
